from datetime import timedelta
import random
from unittest.mock import patch

import config
import calendar_export
import calendar_import
import database
import friends
import gaps
import models
import support


class ProfileTests(support.DatabaseCase):
    """Verify atomic onboarding, editable focus and independent valid favorite targets."""

    def test_complete_onboarding(self):
        """Create one private local profile with focus and only non-secret settings."""
        user_id = database.complete_onboarding(self.connection, ' Alex ', {'sports', 'career'},
                                               'demo', now=support.NOW)
        profile = database.get_user_profile(self.connection, user_id)
        self.assertEqual(profile.display_name, 'Alex')
        self.assertEqual(profile.directions, {'sports', 'career'})
        self.assertEqual(database.get_current_user_id(self.connection), user_id)
        self.assertEqual(database.get_setting(self.connection, 'onboarding_done'), '1')
        self.assertEqual(self.scalar('SELECT is_synthetic FROM users'), 0)
        self.assertEqual(self.scalar('SELECT sharing_opt_in FROM users'), 0)
        self.assertEqual(len(profile.friend_code), config.FRIEND_CODE_LENGTH)
        with self.assertRaises(ValueError):
            database.complete_onboarding(self.connection, 'Other', {'sports'}, 'demo')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM users'), 1)

    def test_invalid_onboarding_is_atomic(self):
        """Leave no user or completion flag after invalid profile or mode input."""
        for name, directions, mode in [('A', {'sports'}, 'demo'), ('Alex', set(), 'demo'),
                                       ('Alex', {'invalid'}, 'demo'), ('Alex', {'sports'}, 'bad')]:
            with self.subTest(name=name, directions=directions, mode=mode):
                with self.assertRaises(ValueError):
                    database.complete_onboarding(self.connection, name, directions, mode)
                self.assertEqual(self.scalar('SELECT COUNT(*) FROM users'), 0)
                self.assertIsNone(database.get_setting(self.connection, 'onboarding_done'))

    def test_profile_edit_preserves_identity(self):
        """Update name and directions atomically without changing code or favorites."""
        user_id = database.complete_onboarding(self.connection, 'Alex', {'sports'}, 'demo')
        before = database.get_user_profile(self.connection, user_id)
        database.update_user_profile(self.connection, user_id, 'Mara', {'career', 'leisure'})
        after = database.get_user_profile(self.connection, user_id)
        self.assertEqual(after.display_name, 'Mara')
        self.assertEqual(after.directions, {'career', 'leisure'})
        self.assertEqual(before.friend_code, after.friend_code)
        with self.assertRaises(ValueError):
            database.update_user_profile(self.connection, user_id, 'Broken', set())
        self.assertEqual(database.get_user_profile(self.connection, user_id).display_name, 'Mara')

    def test_unique_friend_codes_and_retry_bound(self):
        """Avoid collisions deterministically and fail when a generator cannot find a free code."""
        first = database.create_user(self.connection, 'Alex', now=support.NOW)
        second = database.create_user(self.connection, 'Lena', now=support.NOW)
        a = database.get_user_profile(self.connection, first).friend_code
        b = database.get_user_profile(self.connection, second).friend_code
        self.assertNotEqual(a, b)
        self.assertTrue(set(a + b).issubset(config.FRIEND_CODE_ALPHABET))
        with patch.object(config, 'FRIEND_CODE_MAX_ATTEMPTS', 1):
            rng = random.Random(config.RANDOM_SEED)
            with self.assertRaises(ValueError):
                friends.generate_friend_code({a}, rng)

    def test_favorite_kinds_idempotence_and_user_isolation(self):
        """Store series, club and bundle independently and remove only the requested user's row."""
        self.save()
        user_id = database.complete_onboarding(self.connection, 'Alex', {'career'}, 'demo')
        other = database.create_user(self.connection, 'Lena')
        row = database.get_event_row(self.connection, 1)
        targets = [('series', row['series_id']), ('club', row['club_id']),
                   ('bundle', database.get_bundle_id(self.connection, row['bundle_key']))]
        for kind, target_id in targets:
            database.add_favorite(self.connection, user_id, kind, target_id, now=support.NOW)
            database.add_favorite(self.connection, user_id, kind, target_id, now=support.NOW)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM favorites'), 3)
        profile = database.get_user_profile(self.connection, user_id)
        self.assertEqual(profile.favorite_series_ids, {row['series_id']})
        self.assertEqual(profile.favorite_club_ids, {row['club_id']})
        self.assertEqual(profile.favorite_bundle_keys, {row['bundle_key']})
        database.add_favorite(self.connection, other, 'series', row['series_id'])
        database.remove_favorite(self.connection, user_id, 'series', row['series_id'])
        self.assertEqual(database.get_user_profile(self.connection, user_id).favorite_series_ids,
                         set())
        self.assertEqual(database.get_user_profile(self.connection, other).favorite_series_ids,
                         {row['series_id']})

    def test_invalid_favorites_and_unknown_users(self):
        """Reject missing, mixed-kind and malformed references before they reach storage."""
        user_id = database.create_user(self.connection, 'Alex')
        for kind, target in [('unknown', 1), ('series', 999), ('club', True), ('bundle', -1)]:
            with self.assertRaises(ValueError):
                database.add_favorite(self.connection, user_id, kind, target)
        with self.assertRaises(ValueError):
            database.get_user_profile(self.connection, 999)
        with self.assertRaises(ValueError):
            database.add_favorite(self.connection, 999, 'bundle', 1)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM favorites'), 0)


class InteractionTests(support.DatabaseCase):
    """Check state-machine transitions, strict temporal bounds and persistence invariants."""

    def setUp(self):
        """Prepare one future activity and a local user in an in-memory database."""
        super().setUp()
        self.save()
        self.user_id = database.complete_onboarding(self.connection, 'Alex', {'career'}, 'demo')
        self.after = support.record()['end'] + timedelta(seconds=1)

    def act(self, action, now=support.NOW, rating=None):
        """Apply an action to the fixture occurrence with an explicit local clock."""
        return database.save_interaction(self.connection, self.user_id, 1, action, rating, now)

    def test_confirm_cancel_reconfirm(self):
        """Reuse one interaction row while updating the confirmation time on reconfirmation."""
        first = self.act('confirm')
        self.assertEqual(first['status'], 'confirmed')
        cancelled = self.act('cancel')
        self.assertEqual(cancelled['status'], 'cancelled')
        second = self.act('confirm', now=support.NOW + timedelta(minutes=1))
        self.assertEqual(first['id'], second['id'])
        self.assertNotEqual(first['confirmed_at'], second['confirmed_at'])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 1)

    def test_cancelled_export_does_not_reblock_the_gap(self):
        """Keep known exported IDs deduplicated after cancellation, even before feed refresh."""
        event = models.event_from_row(database.get_event_row(self.connection, 1))
        self.act('confirm')
        exported = calendar_export.build_ics(event, now=support.NOW)
        self.act('cancel')
        blocks, _, recognized = calendar_import.parse_calendar(
            exported, event.start.date(), event.end.date() + timedelta(days=1),
            known_event_ids=database.get_known_event_ids(self.connection))
        self.assertEqual(blocks, [])
        self.assertEqual(recognized, {1})
        confirmed = database.get_calendar_confirmations(self.connection, event.start, event.end)
        self.assertTrue(confirmed.empty)
        free = gaps.find_gaps_for_day(event.start.date(), [])
        placed, _ = gaps.assign_events_to_gaps([event], free, set(), now=support.NOW)
        self.assertEqual(sum(len(values) for values in placed.values()), 1)

    def test_attendance_and_rating_transitions(self):
        """Allow attendance after the end and integer star ratings, including later correction."""
        self.act('confirm')
        attended = self.act('attended', now=self.after)
        self.assertIsNone(attended['rating'])
        self.assertEqual(attended['answered_at'], database.to_db_text(self.after))
        self.assertEqual(self.act('rate', now=self.after, rating=4)['rating'], 4)
        self.assertEqual(self.act('rate', now=self.after, rating=5)['rating'], 5)
        with self.assertRaises(ValueError):
            self.act('cancel', now=self.after)

    def test_not_attended_cannot_be_rated(self):
        """Persist a no-show with no rating and reject later rating through the wrong state."""
        self.act('confirm')
        self.assertEqual(self.act('not_attended', now=self.after)['status'], 'not_attended')
        with self.assertRaises(ValueError):
            self.act('rate', now=self.after, rating=1)
        self.assertIsNone(database.get_interaction(self.connection, self.user_id, 1)['rating'])

    def test_invalid_actions_leave_state_unchanged(self):
        """Reject unsupported or duplicate actions without mutating an existing confirmation."""
        for action in ('cancel', 'rate', 'attended', 'unknown'):
            with self.assertRaises(ValueError):
                self.act(action)
        before = self.act('confirm')
        for action in ('confirm', 'attended', 'not_attended', 'rate'):
            with self.assertRaises(ValueError):
                self.act(action)
        self.assertEqual(database.get_interaction(self.connection, self.user_id, 1), before)

    def test_strict_time_boundaries(self):
        """Reject confirm/cancel at start and attendance at the exact end."""
        with self.assertRaises(ValueError):
            self.act('confirm', now=support.record()['start'])
        self.act('confirm')
        with self.assertRaises(ValueError):
            self.act('cancel', now=support.record()['start'])
        with self.assertRaises(ValueError):
            self.act('attended', now=support.record()['end'])

    def test_invalid_ratings(self):
        """Accept only Python integer ratings 1–5 and no rating on other actions."""
        with self.assertRaises(ValueError):
            self.act('confirm', rating=4)
        self.act('confirm')
        self.act('attended', now=self.after)
        for rating in (None, True, 0, 6, 4.0, '4'):
            with self.subTest(rating=rating), self.assertRaises(ValueError):
                self.act('rate', now=self.after, rating=rating)

    def test_unavailable_events_and_references(self):
        """Reject full/closed occurrences and unknown user/event IDs."""
        for status in ('full', 'closed'):
            self.save([support.record(status=status)])
            with self.assertRaises(ValueError):
                self.act('confirm')
        with self.assertRaises(ValueError):
            database.save_interaction(self.connection, self.user_id, 999, 'confirm',
                                      now=support.NOW)
        with self.assertRaises(ValueError):
            database.save_interaction(self.connection, 999, 1, 'confirm', now=support.NOW)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)
